import{_ as r,a0 as a,w as l,s as d,ao as s,I as p,x as n,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在命令列中管理 Wifi 連接 | LCTT x X-CMD","titleTemplate":false,"description":"在命令列中管理 Wifi 連接 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在命令列中管理 Wifi 連接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在命令列中管理 Wifi 連接 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140815 How to manage a WiFi connection from the command line","title":"在命令列中管理 Wifi 連接","tag":"201410","desc":""},"relativePath":"201410/20140815 How to manage a WiFi connection from the command line.md","filePath":"[post].md"}'),m={name:"201410/20140815 How to manage a WiFi connection from the command line.md"};function f(u,t,w,g,c,T){const i=a("Link");return l(),d("div",null,[t[20]||(t[20]=s(`<h1 id="在命令列中管理-wifi-連接" tabindex="-1">在命令列中管理 Wifi 連接 <a class="header-anchor" href="#在命令列中管理-wifi-連接" aria-label="Permalink to “在命令列中管理 Wifi 連接”">​</a></h1><p>無論何時要安裝一款新的 Linux 發行系統，一般的建議都是讓您通過有線連接來接到互聯網的。這主要的原因有兩條：第一，您的無線網卡也許安裝的驅動不正確而不能用；第二，如果您是從命令列中來安裝系統的，管理 WiFi 就非常可怕。我總是試圖避免在命令列中處理 WiFi 。但 Linux 的世界，應具有無所畏懼的精神。如果您不知道怎樣操作，您需要繼續往下來學習之，這就是寫這篇文章的唯一原因。所以我迫使自己學習如何在命令列中管理 WiFi 連接。</p><p>通過命令列來設置連接到 WiFi 當然有很多種方法，但在這篇文章裏，同時也是一個建議，我使用最基本的方法：那就是使用在任何發佈版本中都有的包含在“默認包”裏的程序和工具。或者説我偏向於使用這一種方法。使用此方法顯而易見的好處是這個操作過程能在任意有 Linux 系統的機器上覆用。不好的一點是它相對來説比較複雜。</p><p>首先，我假設您們都已經正確安裝了無線網卡的驅動程序。沒有這前提，後續的一切都如鏡花水月。如果您你機器確實沒有正確安裝上，您應該看看關於您的發佈版本的維基和文檔。</p><p>然後您就可以用如下命令來檢查是哪一個接口來支持無線連接的：</p><pre><code>$ iwconfig
</code></pre><p><img src="https://farm6.staticflickr.com/5578/14725621337_b174a3029c_z.jpg" alt=""></p><p>一般來説，無線接口都叫做 wlan0。當然也有例外的，但在這篇教程中我們將會一直用通用叫法。</p><p>以防萬一，你得確認下以使此接口服務是啓動着的：</p><pre><code>$ sudo ip link set wlan0 up
</code></pre><p>一但確認了無線接口是工作着的，你就可以用如下命令來掃描附近的無線網絡了：</p><pre><code>$ sudo iw dev wlan0 scan | less 
</code></pre><p><img src="https://farm4.staticflickr.com/3847/14909117931_e2f3d0feb0_z.jpg" alt=""></p><p>根據掃描出的結果，可以得到網絡的名字（它的 SSID），它的信息強度，以及它使用的是哪個安全加密的（如：WEP、WPA/WPA2）。從此時起，將會分成兩條路線：情況很好、很容易的以及情況稍微複雜的。</p><p>如果您想連接的網絡是沒有加密的，您可以用下面的命令直接連接：</p><pre><code>$ sudo iw dev wlan0 connect [網絡 SSID]
</code></pre><p>如果網絡是用 WEP 加密的，也非常容易：</p><pre><code>$ sudo iw dev wlan0 connect [網絡 SSID] key 0:[WEP 密鑰]
</code></pre><p>但網絡使用的是 WPA 或 WPA2 協議的話，事情就不好辦了。這種情況，您就得使用叫做 wpa_supplicant 的工具，它默認是沒有的。然後需要修改 /etc/wpa_supplicant/wpa_supplicant.conf 文件，增加如下行：</p><pre><code>network={
    ssid=&quot;[網絡 ssid]&quot;
    psk=&quot;[密碼]&quot;
    priority=1
}
</code></pre><p>我建議你​​在文件的末尾添加它，並確保其他配置都註釋掉。要注意 SSID 和密碼字串都是大小寫敏感的。在技術上您也可以把接入點的名稱當做是 SSID，使用 wpa_supplicant 工具的話會有合適的 SSID 來替代這個名字。</p><p>一旦配置文件修改完成後，在後台啓動此命令：</p><pre><code>$ sudo wpa_supplicant -i wlan0 -c /etc/wpa_supplicant/wpa_supplicant.conf
</code></pre><p>最後，無論是連到開放的網絡還是加密的安全網絡，您都得獲取 IP 地址。簡單地使用如下命令：</p><pre><code>$ sudo dhcpcd wlan0
</code></pre><p>如果一切順利的話，您應該已經通過 DHCP 獲取到了一個全新的本地 IP，這個過程是在後台自動完成的。如果想確認下是否真正連接上的話，您可以再一次輸入如下命令檢查：</p><pre><code>$ iwconfig
</code></pre><p><img src="https://farm4.staticflickr.com/3904/14725573368_7110407db8_z.jpg" alt=""></p>`,28)),p("p",null,[t[3]||(t[3]=n("最後，我認為多次重複第一步的檢查操作是很有必要的。您永遠不會知道什麼時候您的圖形用户界面掛了，或者是什麼時候不能訪問無線連接了，所以現在就準備着用命令來檢測吧。還有，前面提到過的，有很多種方式（如 NetworkManager、",-1)),o(i,{href:"http://wicd.sourceforge.net/"},{default:e(()=>[...t[0]||(t[0]=[n("wicd",-1)])]),_:1}),t[4]||(t[4]=n("、",-1)),o(i,{href:"https://www.archlinux.org/netcfg/"},{default:e(()=>[...t[1]||(t[1]=[n("netcfg",-1)])]),_:1}),t[5]||(t[5]=n("、",-1)),o(i,{href:"https://github.com/rockymeza/wifi"},{default:e(()=>[...t[2]||(t[2]=[n("wifi",-1)])]),_:1}),t[6]||(t[6]=n(" 等等）來管理無線連接。我堅持使用最基本的方式，但在某些情況下，我使用的工具可能您還沒有，所以您在之前就得先下載它們。另一方面，有很多高級的應用程序，他們確實是不包含在“默認包”裏面的，使用它們會大大簡化操作過程。但一般建議是開始的話最好從基本的來。",-1))]),t[21]||(t[21]=p("p",null,"關於從命令列來管理連接 WiFi 您還有其他方式方法嗎？請在評論中讓我們知道。",-1)),t[22]||(t[22]=p("hr",null,null,-1)),p("p",null,[t[8]||(t[8]=n("via: ",-1)),o(i,{href:"http://xmodulo.com/2014/08/manage-wifi-connection-command-line.html"},{default:e(()=>[...t[7]||(t[7]=[n("http://xmodulo.com/2014/08/manage-wifi-connection-command-line.html",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=n("作者：",-1)),o(i,{href:"http://xmodulo.com/author/adrien"},{default:e(()=>[...t[9]||(t[9]=[n("Adrien Brochard",-1)])]),_:1}),t[13]||(t[13]=n(" 譯者：",-1)),o(i,{href:"https://github.com/runningwater"},{default:e(()=>[...t[10]||(t[10]=[n("runningwater",-1)])]),_:1}),t[14]||(t[14]=n(" 校對：",-1)),o(i,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:e(()=>[...t[11]||(t[11]=[n("校對者ID",-1)])]),_:1})]),p("p",null,[t[17]||(t[17]=n("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[15]||(t[15]=[n("LCTT",-1)])]),_:1}),t[18]||(t[18]=n(" 原創翻譯，",-1)),o(i,{href:"http://linux.cn/"},{default:e(()=>[...t[16]||(t[16]=[n("Linux中國",-1)])]),_:1}),t[19]||(t[19]=n(" 榮譽推出",-1))])])}const S=r(m,[["render",f]]);export{C as __pageData,S as default};
